import json
import re

from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message


class SynCareEscalationFormatter(Component):
    display_name = "SynCare Red-flag Escalation Formatter"
    description = "Synthetic red-flag routing payload only; no autonomous emergency instructions."
    inputs = [MessageTextInput(name="input_value", display_name="Red-flag Extraction JSON", required=True)]
    outputs = [Output(display_name="Escalation JSON", name="output", method="format_escalation")]

    def parse_extraction(self):
        raw = self.input_value
        text = (raw.text if isinstance(raw, Message) else str(raw)).strip()
        fence = re.fullmatch(r"```(?:json)?\s*(.*?)\s*```", text, flags=re.IGNORECASE | re.DOTALL)
        if fence:
            text = fence.group(1)
        data = json.loads(text)
        if not isinstance(data, dict) or set(data) != {"symptoms", "medication_adherence", "red_flag", "quote_of_red_flag"}:
            raise ValueError("Extraction must contain exactly the four check-in keys")
        if not isinstance(data["symptoms"], list) or any(not isinstance(s, str) for s in data["symptoms"]):
            raise ValueError("symptoms must be an array of strings")
        if data["medication_adherence"] not in ("regular", "irregular", "unknown"):
            raise ValueError("Invalid medication_adherence")
        if type(data["red_flag"]) is not bool or not isinstance(data["quote_of_red_flag"], str):
            raise ValueError("red_flag must be boolean and quote_of_red_flag string")
        if data["red_flag"] != bool(data["quote_of_red_flag"]):
            raise ValueError("Red flags require a quote; non-flags require an empty quote")
        return data

    def format_escalation(self) -> Message:
        extraction = self.parse_extraction()
        if not extraction["red_flag"]:
            raise ValueError("Only red-flag input belongs on the escalation branch")
        payload = {"action": "escalate_immediately", "reason": extraction["quote_of_red_flag"]}
        result = Message(text=json.dumps(payload, ensure_ascii=False, allow_nan=False))
        self.status = result
        return result
